#!/bin/bash
# Row counts of gym1 data visible to each role (uses a SECURITY INVOKER probe so RLS applies). Run after 06_rls.sh.
source $(dirname $0)/lib.sh
G1=a0000000-0000-0000-0000-000000000001
$PSQL -d t_x -c "create function public._probe() returns text language sql security invoker as \$\$ select (select count(*) from public.classes where gym_id='$G1')||' classes, '||(select count(*) from public.bookings where gym_id='$G1')||' bookings, '||(select count(*) from public.gym_memberships where gym_id='$G1')||' memberships, '||(select count(*) from public.passes where gym_id='$G1')||' passes, '||(select count(*) from public.profiles)||' profiles, '||(select count(*) from public.locations where gym_id='$G1')||' locations, '||(select count(*) from public.audit_events where gym_id='$G1')||' audit' \$\$; grant execute on function public._probe() to authenticated;"
$PSQL -d t_y -c "create function public._probe() returns text language sql security invoker as \$\$ select (select count(*) from public.class_sessions where tenant_id='$G1')||' classes, '||(select count(*) from public.bookings where tenant_id='$G1')||' bookings, '||(select count(*) from public.tenant_users where tenant_id='$G1')||' memberships, '||(select count(*) from public.subscriptions where tenant_id='$G1')||' passes, '||(select count(*) from public.locations where tenant_id='$G1')||' locations' \$\$; grant execute on function public._probe() to authenticated;"
for db in t_x t_y; do echo "#### $db (gym1 rows visible)"; for u in 20 3 4 19 10 2 1; do echo -n "u$u: "; session $db $u "select public._probe();"; done; done
